/*
 * STM32F746G-DISCO Button + Onboard LED
 * Button on D2 (PG6), onboard LED LD1 on D13 (PI1)
 * Uses INPUT_PULLUP so no external resistor needed.
 * Press the button → LD1 turns ON.
 */

int buttonPin = 2;   // D2 = PG6
int ledPin = 13;     // D13 = PI1 = LD1 (green)

void setup() {
  pinMode(buttonPin, INPUT_PULLUP);
  pinMode(ledPin, OUTPUT);
  Serial.begin(115200);
  Serial.println("STM32F746 button test ready");
}

void loop() {
  int state = digitalRead(buttonPin);

  if (state == LOW) {
    digitalWrite(ledPin, HIGH);
    Serial.println("Button PRESSED — LD1 ON");
  } else {
    digitalWrite(ledPin, LOW);
  }

  delay(50);
}
